corrected_code:
const express = require('express');
const Joi = require('joi');
const { EmployeePayrollRecord } = require('../models/payroll');

const app = express();
app.use(express.json());

const directDepositSchema = Joi.object({
  employeeId: Joi.number().integer().positive().required(),
  bankRouting: Joi.string().length(9).regex(/^\d+$/).required(),
  accountNumber: Joi.string().min(8).max(17).regex(/^\d+$/).required()
});

const validateDepositData = (req, res, next) => {
  const { error, value } = directDepositSchema.validate(req.body);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }
  req.payrollData = value;
  next();
};

app.put('/api/payroll/direct-deposit', validateDepositData, async (req, res) => {
  if (!req.user || !req.user.employeeId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { employeeId, bankRouting, accountNumber } = req.payrollData;

  // Enforce that employees can only modify their own payroll records
  if (req.user.employeeId !== employeeId) {
    return res.status(403).json({ error: 'Access denied: cannot modify payroll information of another employee' });
  }

  const record = await EmployeePayrollRecord.findOne({ where: { employeeId } });
  if (!record) {
    return res.status(404).json({ error: 'Employee record not found' });
  }

  record.directDepositRouting = bankRouting;
  record.directDepositAccount = accountNumber;
  record.updatedAt = new Date();
  await record.save();

  res.json({ success: true, message: 'Direct deposit routing updated' });
});

app.listen(7006);
